const startPaymentSend = `-- name: StartPaymentSend :one
UPDATE payments SET first_sent_at=COALESCE(first_sent_at,now()) WHERE id=$1 RETURNING id, agreement_id, tier_id, amount_kopecks, renewal, save_method, request_body, provider_id, confirmation_url, status, created_at, first_sent_at, available_at, lease_until, completed_at, period_start, period_end, failure_code, attempts
`

func (q *Queries) StartPaymentSend(ctx context.Context, id string) (Payment, error) {
	row := q.db.QueryRow(ctx, startPaymentSend, id)
	var i Payment
	err := row.Scan(
		&i.ID,
		&i.AgreementID,
		&i.TierID,
		&i.AmountKopecks,
		&i.Renewal,
		&i.SaveMethod,
		&i.RequestBody,
		&i.ProviderID,
		&i.ConfirmationUrl,
		&i.Status,
		&i.CreatedAt,
		&i.FirstSentAt,
		&i.AvailableAt,
		&i.LeaseUntil,
		&i.CompletedAt,
		&i.PeriodStart,
		&i.PeriodEnd,
		&i.FailureCode,
		&i.Attempts,
	)
	return i, err
}

